public interface Scanner   { void scan(Document d); }
public interface FaxMachine { void fax(Document d); }

public class SimplePrinter implements Printer {  // only what it can do
    public void print(Document d) { /* real */ }
}
public class MultiFunctionPrinter implements Printer, Scanner, FaxMachine {
    public void print(Document d) { /* real */ }
    public void scan(Document d)  { /* real */ }
    public void fax(Document d)   { /* real */ }
