// Violates Law of Demeter: InvoiceService reaches through 3 objects
public class InvoiceService {
    public void printInvoice(Order order) {
        // Train wreck: order -> customer -> account -> balance
        double balance = order.getCustomer().getAccount().getBalance();
        String name = order.getCustomer().getName();
        System.out.println(name + " : " + balance);
    }
    // InvoiceService now depends on: Order's API, Customer's API (getName AND
// getAccount), and Account's API (getBalance). Change Account to expose balance
// via getAvailableFunds() and this method breaks — even though it never owned
// an Account.
}
```

```java
// Fixed: Order exposes only what the caller needs; the caller knows nothing
// about Customer or Account.
public class Order {
    private final Customer customer;
    public Order(Customer customer) { this.customer = customer; }

    // Order delegates — the knowledge that 'a customer has an account with a
// balance' lives in ONE place (here), not scattered across callers.
    public double getCustomerBalance() { return customer.getAccountBalance(); }
    public String getCustomerName()   { return customer.getName(); }
}
public class Customer {
    private final Account account;
    public double getAccountBalance() { return account.getBalance(); }
}
public class InvoiceService {
    public void printInvoice(Order order) {
        // Only talks to its immediate friend (order). No train wreck.
        System.out.println(order.getCustomerName() + " : " + order.getCustomerBalance());
    }
}
// Now InvoiceService depends only on Order. Customer and Account can change
// freely as long as Order's contract holds. Coupling dropped from 3 classes to 1.
